// Stopped-container probe helpers and OFFLINE Ed25519 signature-harvest
// verification against fixtures (issue #279, docs/architecture.md §11.3 E3).
// Zero Docker, zero model inference: every function here is pure or reads
// only from a host-side fixture tree this suite builds itself. The one real
// cryptographic operation — verifying a signature against the contract's
// canonicalizeApplication — uses a REAL Ed25519 keypair generated by Web
// Crypto (the same primitive backend/src/lib/signing.ts verifies with), never
// a stub.
import { canonicalizeApplication } from "@robotmoney/contract";
import { describe, expect, test } from "bun:test";
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import {
  findByName,
  findMatching,
  isMissingMemberOnlyTarFailure,
  toContainerPath,
} from "../../../evals/onboarding/support/probe.ts";
import {
  classifyPayloadOnDisk,
  explainHarvestFailure,
  explainPayloadOnDisk,
  explainTruncation,
  explainUnscannedFiles,
  findApplicationPayloadOnDisk,
  harvestSignedApplication,
  joinWrappedLines,
  KEYSTORE_PATH_PATTERN,
  scanBase64Candidates,
} from "../../../evals/onboarding/support/signature-harvest.ts";

const repoRoot = join(import.meta.dir, "..", "..", "..");

describe("probe.ts — container-listing helpers (pure)", () => {
  test("toContainerPath normalises a tar member path to an absolute container path", () => {
    expect(toContainerPath("home/agent/x")).toBe("/home/agent/x");
    expect(toContainerPath("/home/agent/x")).toBe("/home/agent/x");
  });

  test("findByName / findMatching filter an existing listing rather than calling docker", () => {
    const listing = ["home/agent/SKILL.md", "home/agent/.rmpc/identity.json", "home/agent/notes.txt"];
    expect(findByName("c", "SKILL.md", listing)).toEqual(["home/agent/SKILL.md"]);
    expect(findMatching("c", KEYSTORE_PATH_PATTERN, listing)).toEqual(["home/agent/.rmpc/identity.json"]);
  });

  test("isMissingMemberOnlyTarFailure tolerates ONLY a genuine 'not found in archive' trailer", () => {
    expect(isMissingMemberOnlyTarFailure("tar: home/agent/*.sig: Not found in archive\ntar: Exiting with failure status due to previous errors\n")).toBe(true);
  });

  test("isMissingMemberOnlyTarFailure does NOT tolerate a hard error even alongside the generic trailer", () => {
    expect(isMissingMemberOnlyTarFailure("tar: home/agent/x: Cannot open: Permission denied\ntar: Exiting with failure status due to previous errors\n")).toBe(false);
    expect(isMissingMemberOnlyTarFailure("tar: Exiting with failure status due to previous errors\n")).toBe(false);
  });
});

describe("signature-harvest.ts — base64 candidate scanning (pure)", () => {
  const fakeKey = "A".repeat(43) + "="; // 44 chars: exactly a 32-byte ed25519 public key shape
  const fakeSig = "B".repeat(86) + "=="; // 88 chars: exactly a 64-byte ed25519 signature shape

  test("scans exact-length base64 tokens and rejects a longer padded blob's prefix", () => {
    const candidates = scanBase64Candidates(`publicKey=${fakeKey} signature=${fakeSig}`);
    expect(candidates.publicKeys).toContain(fakeKey);
    expect(candidates.signatures).toContain(fakeSig);
  });

  test("a token immediately followed by more base64 (a longer blob) is NOT harvested as the shorter shape", () => {
    const longer = "C".repeat(50); // no `=` boundary, so no 44-char prefix should be harvested
    const candidates = scanBase64Candidates(longer);
    expect(candidates.publicKeys).toEqual([]);
  });

  test("joinWrappedLines re-joins an encoder-wrapped token so the wrapped copy is ALSO scanned", () => {
    const wrapped = fakeSig.slice(0, 76) + "\n" + fakeSig.slice(76);
    expect(joinWrappedLines(wrapped)).toBe(fakeSig);
    const candidates = scanBase64Candidates(wrapped);
    expect(candidates.signatures).toContain(fakeSig);
  });

  test("the raw pass still finds tokens the joined pass would glue together", () => {
    const candidates = scanBase64Candidates(`${fakeKey}\n${fakeSig}`);
    expect(candidates.publicKeys).toContain(fakeKey);
    expect(candidates.signatures).toContain(fakeSig);
  });
});

describe("signature-harvest.ts — on-disk payload classification (pure)", () => {
  const canonical = canonicalizeApplication({ name: "Onboarding Eval abc123", contact: "onboarding-eval-abc123@example.test", publicKey: "pk" });

  test("byte-exact match", () => {
    const contents = new Map([["/f", canonical]]);
    expect(classifyPayloadOnDisk(contents, [canonical], "onboarding-eval-abc123@example.test")).toEqual({ match: "byte-exact", bytes: JSON.stringify(canonical) });
  });

  test("trailing-whitespace-only match — the `echo > F` defect", () => {
    const withNewline = `${canonical}\n`;
    const contents = new Map([["/f", withNewline]]);
    const result = classifyPayloadOnDisk(contents, [canonical], "onboarding-eval-abc123@example.test");
    expect(result.match).toBe("trailing-whitespace-only");
  });

  test("shaped-but-different — a payload-looking file that isn't byte-identical", () => {
    const shaped = `{"name":"Onboarding Eval abc123","contact":"onboarding-eval-abc123@example.test","publicKey":"different"}`;
    const contents = new Map([["/f", shaped]]);
    const result = classifyPayloadOnDisk(contents, [canonical], "onboarding-eval-abc123@example.test");
    expect(result.match).toBe("shaped-but-different");
  });

  test("none — nothing payload-shaped was left behind", () => {
    const contents = new Map([["/f", "totally unrelated content"]]);
    expect(classifyPayloadOnDisk(contents, [canonical], "onboarding-eval-abc123@example.test")).toEqual({ match: "none", bytes: null });
  });

  test("findApplicationPayloadOnDisk matches by CONTENT, never by filename", () => {
    const contents = new Map([["/anything.dat", canonical]]);
    expect(findApplicationPayloadOnDisk(contents, canonical, "onboarding-eval-abc123@example.test")).toBe(canonical);
  });
});

describe("signature-harvest.ts — explain* renders evidence a human can read", () => {
  test("explainHarvestFailure distinguishes 'no material' from 'material found, nothing verifies'", () => {
    const none = explainHarvestFailure({ candidatePublicKeys: 0, candidateSignatures: 0, filesScanned: 0, sources: ["transcript"] });
    expect(none).toContain("NO SIGNATURE MATERIAL ANYWHERE");
    const some = explainHarvestFailure({ candidatePublicKeys: 2, candidateSignatures: 3, filesScanned: 1, sources: ["transcript"] });
    expect(some).toContain("SIGNATURE MATERIAL FOUND BUT NOTHING VERIFIED");
  });

  test("explainTruncation is silent when nothing was truncated, and reports counts when it was", () => {
    expect(explainTruncation(undefined)).toBe("");
    expect(explainTruncation({ publicKeys: 1, signatures: 2 })).toMatch(/TRUNCATED.*1 public key.*2 signature/s);
  });

  test("explainUnscannedFiles is silent when every file was read, and reports counts when it was not", () => {
    expect(explainUnscannedFiles(undefined)).toBe("");
    expect(explainUnscannedFiles({ oversized: 0, unreadable: 0 })).toBe("");
    expect(explainUnscannedFiles({ oversized: 2, unreadable: 1 })).toMatch(/DID NOT READ EVERY FILE/);
  });

  test("explainPayloadOnDisk is silent for 'none' and names the specific defect otherwise", () => {
    expect(explainPayloadOnDisk(undefined)).toBe("");
    expect(explainPayloadOnDisk({ match: "none", bytes: null })).toBe("");
    expect(explainPayloadOnDisk({ match: "trailing-whitespace-only", bytes: '"x\\n"' })).toContain("CANONICAL EXCEPT FOR SURROUNDING WHITESPACE");
  });
});

describe("harvestSignedApplication — end-to-end OFFLINE verification with a REAL Ed25519 keypair", () => {
  const application = { name: "Onboarding Eval real-key", contact: "onboarding-eval-real-key@example.test" };

  async function realKeypairAndSignature(): Promise<{ publicKeyB64: string; signatureB64: string; canonical: string }> {
    const keyPair = (await crypto.subtle.generateKey({ name: "Ed25519" }, true, ["sign", "verify"])) as CryptoKeyPair;
    const rawPublic = await crypto.subtle.exportKey("raw", keyPair.publicKey);
    const canonical = canonicalizeApplication({ ...application, publicKey: Buffer.from(rawPublic).toString("base64") });
    const signature = await crypto.subtle.sign({ name: "Ed25519" }, keyPair.privateKey, new TextEncoder().encode(canonical));
    return {
      publicKeyB64: Buffer.from(rawPublic).toString("base64"),
      signatureB64: Buffer.from(signature).toString("base64"),
      canonical,
    };
  }

  test("a signature the agent left in the TRANSCRIPT verifies against the contract's canonical bytes", async () => {
    const { publicKeyB64, signatureB64, canonical } = await realKeypairAndSignature();
    const hostDir = mkdtempSync(join(tmpdir(), "harvest-test-"));
    try {
      const transcript = `some tool output\npublicKey=${publicKeyB64}\nsignature=${signatureB64}\nmore output`;
      const result = await harvestSignedApplication({ repoRoot, transcript, hostDir, application });
      expect(result.verified).not.toBeNull();
      expect(result.verified?.publicKey).toBe(publicKeyB64);
      expect(result.verified?.signature).toBe(signatureB64);
      expect(result.verified?.canonicalPayloadExpected).toBe(canonical);
    } finally {
      rmSync(hostDir, { recursive: true, force: true });
    }
  });

  test("a signature found only in an EXTRACTED FILE (not the transcript) also verifies, and the byte-exact payload on disk is reported", async () => {
    const { publicKeyB64, signatureB64, canonical } = await realKeypairAndSignature();
    const hostDir = mkdtempSync(join(tmpdir(), "harvest-test-"));
    try {
      const nested = join(hostDir, "home", "agent");
      mkdirSync(nested, { recursive: true });
      writeFileSync(join(nested, "app.json"), canonical); // byte-exact, no trailing newline
      writeFileSync(join(nested, "sig.b64"), `key=${publicKeyB64}\nsig=${signatureB64}\n`);
      const result = await harvestSignedApplication({ repoRoot, transcript: "no signature material in the transcript at all", hostDir, application });
      expect(result.verified).not.toBeNull();
      expect(result.verified?.canonicalPayloadOnDisk).toBe(canonical);
    } finally {
      rmSync(hostDir, { recursive: true, force: true });
    }
  });

  test("no candidates anywhere reports zero candidates, and the canonical shape the harness expected", async () => {
    const hostDir = mkdtempSync(join(tmpdir(), "harvest-test-"));
    try {
      const result = await harvestSignedApplication({ repoRoot, transcript: "the agent produced nothing signature-shaped", hostDir, application });
      expect(result.verified).toBeNull();
      expect(result.diagnostics.candidatePublicKeys).toBe(0);
      expect(result.diagnostics.candidateSignatures).toBe(0);
      expect(result.diagnostics.canonicalShapeExpected).toContain(application.contact);
    } finally {
      rmSync(hostDir, { recursive: true, force: true });
    }
  });

  test("a WRONG key/signature pair (canonicalization drift) never verifies, even though material was found", async () => {
    const { publicKeyB64 } = await realKeypairAndSignature();
    const { signatureB64: wrongSignature } = await realKeypairAndSignature(); // a signature from a DIFFERENT key
    const hostDir = mkdtempSync(join(tmpdir(), "harvest-test-"));
    try {
      const transcript = `publicKey=${publicKeyB64}\nsignature=${wrongSignature}\n`;
      const result = await harvestSignedApplication({ repoRoot, transcript, hostDir, application });
      expect(result.verified).toBeNull();
      expect(result.diagnostics.candidatePublicKeys).toBeGreaterThan(0);
      expect(result.diagnostics.candidateSignatures).toBeGreaterThan(0);
    } finally {
      rmSync(hostDir, { recursive: true, force: true });
    }
  });

  // ── No silent caps (issue #280) ────────────────────────────────────────────
  // The candidate cap was once 25 per dimension, justified as unable to bite on
  // a genuine run. A real signature-harvest run once produced 3 candidate
  // public keys and 34 candidate SIGNATURES, so 9 signatures would have gone
  // untested with no indication in the output — and if the agent's real
  // signature had been among them, the harness would have reported a
  // canonicalization drift that never happened. MAX_CANDIDATES is 500 now;
  // these cases prove the cap is both ABOVE that observed shape and that a
  // search that DOES exceed it says so rather than staying silent.
  const B64_CHARS = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  // 43 base64 chars + "=" — exactly a 32-byte ed25519 public-key shape. `i`
  // selects a unique two-character prefix so every generated token is distinct
  // (Set-deduplicated by scanBase64Candidates).
  function fakePublicKeyLike(i: number): string {
    const a = B64_CHARS[i % B64_CHARS.length];
    const b = B64_CHARS[Math.floor(i / B64_CHARS.length) % B64_CHARS.length];
    return `${a}${b}${"D".repeat(41)}=`;
  }
  // 86 base64 chars + "==" — exactly a 64-byte ed25519 signature shape.
  function fakeSignatureLike(i: number): string {
    const a = B64_CHARS[i % B64_CHARS.length];
    const b = B64_CHARS[Math.floor(i / B64_CHARS.length) % B64_CHARS.length];
    return `${a}${b}${"C".repeat(84)}==`;
  }

  test("the observed real-run shape (3 candidate keys, 34 candidate signatures) is asserted UN-TRUNCATED, and the real pair still verifies", async () => {
    const { publicKeyB64, signatureB64, canonical } = await realKeypairAndSignature();
    const hostDir = mkdtempSync(join(tmpdir(), "harvest-test-"));
    try {
      const decoyKeys = [fakePublicKeyLike(1), fakePublicKeyLike(2)]; // + the real key = 3
      // + the real signature, placed LAST — the position an old, lower cap
      // (25) would have discarded.
      const decoySignatures = Array.from({ length: 33 }, (_, i) => fakeSignatureLike(i)); // + the real signature = 34
      const transcript = [...decoyKeys, publicKeyB64, ...decoySignatures, signatureB64].join("\n");
      const result = await harvestSignedApplication({ repoRoot, transcript, hostDir, application });
      expect(result.diagnostics.candidatePublicKeys).toBe(3);
      expect(result.diagnostics.candidateSignatures).toBe(34);
      expect(result.diagnostics.truncatedCandidates).toBeUndefined();
      expect(result.verified).not.toBeNull();
      expect(result.verified?.signature).toBe(signatureB64);
      expect(result.verified?.canonicalPayloadExpected).toBe(canonical);
    } finally {
      rmSync(hostDir, { recursive: true, force: true });
    }
  });

  test("a search that DOES exceed MAX_CANDIDATES=500 reports the truncation instead of staying silent", async () => {
    const hostDir = mkdtempSync(join(tmpdir(), "harvest-test-"));
    try {
      // 501 unique signature-shaped tokens: one over the cap. No real pair is
      // present — this case is purely about the truncation REPORT, not
      // verification.
      const signatures = Array.from({ length: 501 }, (_, i) => fakeSignatureLike(i));
      const transcript = [fakePublicKeyLike(0), ...signatures].join("\n");
      const result = await harvestSignedApplication({ repoRoot, transcript, hostDir, application });
      expect(result.diagnostics.candidateSignatures).toBe(501);
      expect(result.diagnostics.truncatedCandidates).toEqual({ publicKeys: 0, signatures: 1 });
      expect(explainTruncation(result.diagnostics.truncatedCandidates)).toMatch(/TRUNCATED.*1 signature\(s\).*NEVER TESTED/s);
    } finally {
      rmSync(hostDir, { recursive: true, force: true });
    }
  });

  test("an oversized file is skipped, not scanned — real material hidden solely inside it is never found, and the skip is counted", async () => {
    const { publicKeyB64, signatureB64 } = await realKeypairAndSignature();
    const hostDir = mkdtempSync(join(tmpdir(), "harvest-test-"));
    try {
      // The ONLY copy of the material sits inside a file just over the 2 MiB
      // cap, so if the cap is honoured there is nothing left to verify.
      writeFileSync(
        join(hostDir, "huge.log"),
        `${"x".repeat(2 * 1024 * 1024 + 1)}\npublicKey=${publicKeyB64}\nsignature=${signatureB64}\n`,
      );
      const result = await harvestSignedApplication({
        repoRoot,
        transcript: "no signature material in the transcript at all",
        hostDir,
        application,
      });
      expect(result.verified).toBeNull();
      expect(result.diagnostics.filesScanned).toBe(0);
      expect(result.diagnostics.candidatePublicKeys).toBe(0);
      expect(result.diagnostics.unscannedFiles).toEqual({ oversized: 1, unreadable: 0 });
      expect(explainUnscannedFiles(result.diagnostics.unscannedFiles)).toMatch(/DID NOT READ EVERY FILE.*1 file\(s\) exceeded/s);
    } finally {
      rmSync(hostDir, { recursive: true, force: true });
    }
  });
});
